SIDE = "left"
SLOT_PARK = (0.0, 0.0, -5.0)
HAND_BODIES = ("openarm_left_hand", "openarm_left_right_finger", "openarm_left_left_finger")


def add_object_slots(spec, n):
    """Adds n spare box geoms (names fc_slot_<i>) to the world body of a model spec: stand-ins for unknown objects, parked below the floor and invisible until used.

    Args:
        spec (mujoco.MjSpec): The model spec (a load_task hook).
        n (int): The number of slots.
    """
    for i in range(n):
        spec.worldbody.add_geom(name=f"fc_slot_{i}", type=mujoco.mjtGeom.mjGEOM_BOX, size=[0.01, 0.01, 0.01], pos=list(SLOT_PARK), rgba=[0.8, 0.3, 0.1, 0.0], contype=1, conaffinity=1)


class PathClearance:
    """How close the left arm's links (the hand and fingers apart) come to the furniture and the objects, for joint vectors at a stance; and the whole robot against them.

    The world geoms are every collidable geom that is not the robot, not the floor plane and not the beaker (the beaker is the target); the object slots are among them. Distances are
    mujoco.mj_geomDistance values (negative: penetration), looked up to `look` metres.
    """

    def __init__(self, model, base_z, look=0.1):
        self.model, self.base_z, self.look = model, float(base_z), float(look)
        m = model
        self.d = mujoco.MjData(m)
        root = m.body("base_link").id

        def under(b, r):
            while b > 0:
                if b == r:
                    return True
                b = int(m.body_parentid[b])
            return False
        col = [bool(m.geom_contype[g] or m.geom_conaffinity[g]) for g in range(m.ngeom)]
        bname = lambda g: m.body(int(m.geom_bodyid[g])).name
        beaker = m.body("task_beaker").id
        self.hand = [g for g in range(m.ngeom) if col[g] and bname(g) in HAND_BODIES]
        self.arm = [g for g in range(m.ngeom) if col[g] and bname(g).startswith("openarm_left_") and not bname(g).endswith("link0") and g not in self.hand]
        self.world = [g for g in range(m.ngeom) if col[g] and not under(int(m.geom_bodyid[g]), root) and not under(int(m.geom_bodyid[g]), beaker) and int(m.geom_type[g]) != int(mujoco.mjtGeom.mjGEOM_PLANE)]
        self.robot = [g for g in range(m.ngeom) if col[g] and under(int(m.geom_bodyid[g]), root)]
        self.qadr = arm_ids(m, SIDE)["qadr"]
        self.pedestal = [m.joint(jn).qposadr[0] for jn in robot_specs.PEDESTAL_SPECS["joints"]]
        self.ft = np.zeros(6)
        for sd, home in (("left", TASK_CFG["home_q_left"]), ("right", TASK_CFG["home_q_right"])):
            for a, v in zip(arm_ids(m, sd)["qadr"], home):
                self.d.qpos[a] = v
            for j in arm_ids(m, sd)["finger_jnt"]:
                self.d.qpos[m.jnt_qposadr[j]] = STAGING_CFG["finger_open"]
        self.home_left = [float(v) for v in TASK_CFG["home_q_left"]]      # body_distance puts the left arm back here (arm_distances leaves it at the last joint vector it was given)
        self.slot_geoms = [g for g in range(m.ngeom) if (m.geom(g).name or "").startswith("fc_slot")]

    def place(self, stance):
        d = self.d
        x, y, th, q = stance
        d.qpos[0:7] = [x, y, self.base_z, math.cos(th / 2), 0.0, 0.0, math.sin(th / 2)]
        for a in self.pedestal:
            d.qpos[a] = q

    def _min(self, groups, others, with_pair=False):
        m, d = self.model, self.d
        best, pair = self.look, ""
        for a in groups:
            for b in others:
                if np.linalg.norm(d.geom_xpos[a] - d.geom_xpos[b]) - m.geom_rbound[a] - m.geom_rbound[b] > best:
                    continue
                v = mujoco.mj_geomDistance(m, d, a, b, self.look, self.ft)
                if v < best:
                    best, pair = v, f"{m.geom(a).name} vs {m.geom(b).name}"
        return (best, pair) if with_pair else best

    def arm_distances(self, stance, Q):
        """For joint vectors Q (c, 7) at a stance: (hand_min (c,), arm_min (c,), hand_pair, arm_pair): the smallest distance of the hand and fingers, and of the other left arm links, to the world geoms."""
        self.place(stance)
        d, m = self.d, self.model
        hm, am = np.full(len(Q), self.look), np.full(len(Q), self.look)
        hp, ap = [""] * len(Q), [""] * len(Q)
        for i, q in enumerate(np.atleast_2d(Q)):
            d.qpos[self.qadr] = q
            mujoco.mj_kinematics(m, d)
            hm[i], hp[i] = self._min(self.hand, self.world, True)
            am[i], ap[i] = self._min(self.arm, self.world, True)
        return hm, am, hp, ap

    def body_distance(self, stance):
        """The smallest distance of the whole robot (both arms at home, the camera box on the torso included) to the world geoms (bench, hotplate, objects) at a stance."""
        self.place(stance)
        d, m = self.d, self.model
        d.qpos[self.qadr] = self.home_left                    # P3 (M181): both arms at home as documented; arm_distances leaves the left arm at the last joint vector it tried
        mujoco.mj_kinematics(m, d)
        return self._min(self.robot, self.world, True)



def _wrap_deg(d):
    """A turn in degrees as -180 .. 180 (counter-clockwise positive)."""
    return d - 360 if d > 180 else d


def choose_place_window(passing_deg, step, need):
    """The place angle from which hand turns work (the pure part of FullCheck._place_window; decisions-log M183 and M184).

    The turns are `step` degrees apart all the way round (0 to 360 - step). A window is a run of consecutive working turns, and the circle is closed: 345, 350, 355, 0, 5 is ONE window.
    Rules: the widest window (most turns) wins; two equally wide windows: the one that comes first going up from 0 degrees, a window across 0 counting as the one at 0 (so it wins a tie);
    the chosen angle is the middle turn of the window listed from its first to its last turn: with an odd number of turns the exact middle, with an even number (the middle falls between two
    steps) the later of the two middle turns. The width is (turns - 1) * step, first turn to last; under `need` degrees there is no window.

    Args:
        passing_deg (iterable of int): The working turns, degrees, multiples of `step`, 0 to 360 - step.
        step (int): The spacing of the turns, degrees.
        need (float): The smallest width (degrees) of the chosen window.

    Returns:
        dict: "theta_deg" (chosen turn, -180..180, or None), "window_deg" ([first, last] or None), "width_deg", "passing_deg" (wrapped), "windows" (every run [first, last], wrapped), "reason" ("" or why none).
    """
    ps = set(int(d) % 360 for d in passing_deg)
    turns = list(range(0, 360, step))
    runs, cur = [], []
    for deg in turns:
        if deg in ps:
            cur.append(deg)
        elif cur:
            runs.append(cur)
            cur = []
    if cur:
        runs.append(cur)
    if len(runs) > 1 and runs[0][0] == 0 and runs[-1][-1] == 360 - step:       # a window across 0 degrees
        runs[0] = runs[-1] + runs[0]
        runs.pop()
    out = {"theta_deg": None, "window_deg": None, "width_deg": 0, "passing_deg": [_wrap_deg(d) for d in turns if d in ps], "windows": [[_wrap_deg(r[0]), _wrap_deg(r[-1])] for r in runs], "reason": ""}
    if not runs:
        out["reason"] = "no place angle window: no hand turn works"
        return out
    best = max(runs, key=len)                          # max keeps the first of equals (see the tie rule above)
    out["window_deg"], out["width_deg"] = [_wrap_deg(best[0]), _wrap_deg(best[-1])], (len(best) - 1) * step
    if out["width_deg"] < need:
        out["reason"] = f"no place angle window: the widest window of working hand turns is {out['width_deg']} degrees ({out['window_deg'][0]} to {out['window_deg'][1]}), under the {need} degrees minimum"
        return out
    out["theta_deg"] = _wrap_deg(best[len(best) // 2])
    return out


def pose_ik_summary(log, limit):
    """The pose_ik_iterations report from FullCheck.pose_ik_log: the iterations the accepted start of each stop used (typical = median, 90th percentile, largest, and how many sit at `limit`), and
    how many batches had at least one start run to the limit (random starts often do; they are not accepted)."""
    acc = [e["accepted"] for e in log if e["accepted"] is not None]
    out = {"limit": limit, "stops_accepted": len(acc), "batches": len(log), "batches_not_accepted": len(log) - len(acc),
           "batches_with_a_start_at_limit": sum(1 for e in log if e["batch_at_limit"] > 0)}
    if acc:
        a = np.asarray(acc)
        out.update(typical=float(np.median(a)), p90=float(np.percentile(a, 90)), largest=int(a.max()), accepted_at_limit=int(np.sum(a >= limit)))
    return out


class FullCheck:
    """The full check of a stance candidate (see the module docstring).

    Attributes:
        sim (RobotSimulator): The check's own simulation (its model has the object slots).
        model (mujoco.MjModel): Its model (private: the slots, the arm collision checkers' copies and the renderers belong to the check).
        scene_data (mujoco.MjData): Its scene data (the objects placed).
        chk (StanceChecks): The clearance, view and occlusion checks on the private model (occluders "all").
        stats (dict): Counters of the last check: IK batches and starts, solves, cache hits.
        seconds (dict): Seconds spent per part in the last check.
    """

    def __init__(self, cfg=FULLCHECK_CFG, maps=None, task_cfg=TASK_CFG, say=print):
        """Loads the simulation (once), builds the checks.

        Args:
            cfg (dict): FULLCHECK_CFG. Defaults to it.
            maps (dict or None): {("left", bin): ReachMap} (src/reach_map.load_map), used to order the approach directions of a point without a required one. Defaults to None: ordered by the angle only.
            task_cfg (dict): TASK_CFG (the scene). Defaults to it.
            say (callable): Where progress lines go. Defaults to print.
        """
        self.cfg, self.maps, self.say = cfg, maps or {}, say
        self.pose_ik_log = []                                  # one entry per IK batch of a skill stop (see _log_ik)
        t0 = time.perf_counter()
        self.sim = load_task(task_cfg, cameras=True, extra_hooks=[lambda spec: add_object_slots(spec, cfg["object_slots"])])
        self.model, self.scene_data = self.sim.model, self.sim.data
        m = self.model
        mujoco.mj_forward(m, self.scene_data)
        self.rg = robot_geometry(m)
        slots = [g for g in range(m.ngeom) if (m.geom(g).name or "").startswith("fc_slot")]
        self.chk = StanceChecks(m, self.scene_data, self.rg["base_z"], occluders="all", extra_geoms=slots)
        self.C = grasp_cfg(m, SIDE)
        self.chain = arm_chain(m, SIDE)
        self.pad = np.array(self.C["pad_center_in_tcp"])
        self.lo, self.hi = joint_bounds(m, SIDE, self.C)
        self.centres = np.array([bin_center(k, self.C) for k in range(self.C["n_bins"])])
        self.shoulder = np.asarray(self.rg["shoulder"][SIDE], float)
        Rpi = np.column_stack([self.C["closing_axis"], np.cross(self.C["approach_axis"], self.C["closing_axis"]), self.C["approach_axis"]])      # the pad frame in the tool frame (as MinkArm)
        _, Rh = batch_fk(self.chain, np.asarray(task_cfg["home_q_left"], float)[None], self.pad)
        z = np.array([1.0, 0.0, 0.0])                                    # the skill approaches along the robot's forward direction (the torso frame's x) with the hand level (plan_pick: pad_rotation)
        hint = (Rh[0] @ Rpi)[:, 0]                                        # the closing axis of the pad at the zombie pose keeps the hand's roll, as pad_rotation's closing_hint
        x = hint - z * float(hint @ z)
        x[2] = 0.0
        x /= np.linalg.norm(x)
        self.R_skill = np.column_stack([x, np.cross(z, x), z]) @ Rpi.T     # the skill's tool frame rotation in the torso frame (level, straight forward)
        self.clear = PathClearance(m, self.rg["base_z"])
        self._slots = [g for g in range(m.ngeom) if (m.geom(g).name or "").startswith("fc_slot")]
        self._checkers = {}
        self.rng = np.random.default_rng(11)
        self.zombie_q = np.array(TASK_CFG[f"home_q_{SIDE}"], float)    # the arm's start pose (the zombie pose): where the robot's own solver starts a skill
        self.start_log = []                                         # one entry per solved stop (see _log_stop): how it was started, whether a random rescue was used
        self.cache = {}
        self.stats, self.seconds = {}, {}
        self.start_log = []
        self.load_seconds = time.perf_counter() - t0
        self.objects = []
        self._beaker_free = m.joint("task_beaker_free").qposadr[0]

    # ------------------------------------------------------------------ scene
    def sync(self, source_data):
        """Copies the object poses of a running simulation's data into the check's scene (read only on the source)."""
        q = np.asarray(source_data.qpos, float)
        if q.shape != self.chk.q_scene.shape:
            raise ValueError("the running simulation's state has another size than the check's model")
        self.chk.q_scene = q.copy()

    def set_objects(self, objects):
        """Puts the unknown objects of the table into the model's slots (the bounding box of each outline, its height range), parks the unused slots.

        Raises:
            ValueError: If there are more objects than slots.
        """
        m = self.model
        if len(objects) > len(self._slots):
            raise ValueError(f"{len(objects)} objects but only {len(self._slots)} slots (FULLCHECK_CFG['object_slots'])")
        for i, g in enumerate(self._slots):
            if i < len(objects):
                o = np.asarray(objects[i]["outline"], float)
                z0, z1 = objects[i]["height_range"]
                lo, hi = o.min(axis=0), o.max(axis=0)
                m.geom_pos[g] = [(lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, (z0 + z1) / 2]
                m.geom_size[g] = [max((hi[0] - lo[0]) / 2, 1e-3), max((hi[1] - lo[1]) / 2, 1e-3), max((z1 - z0) / 2, 1e-3)]
                m.geom_rgba[g, 3] = 1.0
            else:
                m.geom_pos[g], m.geom_size[g], m.geom_rgba[g, 3] = SLOT_PARK, [0.01, 0.01, 0.01], 0.0
            m.geom_rbound[g] = float(np.linalg.norm(m.geom_size[g]))
        self.objects = list(objects)

    def _key(self, stance, points, objects, approach_bin):
        h = hashlib.sha256()
        h.update(np.round(np.asarray(stance, float), 6).tobytes())
        for pt in points:
            h.update(np.round(np.asarray(pt["p"], float), 6).tobytes() + repr((pt.get("bin"), pt.get("path"), pt.get("arm"), pt.get("pose"), pt.get("pivot"))).encode())
        for o in objects:
            h.update(np.round(np.asarray(o["outline"], float), 6).tobytes() + np.round(np.asarray(o["height_range"], float), 6).tobytes() + str(o.get("id")).encode())
        h.update(repr(approach_bin).encode() + repr(sorted(self.cfg.items(), key=lambda kv: kv[0])).encode() + repr(sorted(STANCE_REQUIREMENTS.items())).encode() + repr(sorted(EAGLE_MOUNT.items())).encode())      # the camera's mount is part of the answer (it sets the view)
        h.update(np.round(self.chk.q_scene[self._beaker_free:self._beaker_free + 7], 6).tobytes())                    # the beaker's pose
        hp = self.model.body("task_hotplate").id
        h.update(np.round(self.model.body_pos[hp], 6).tobytes())
        return h.hexdigest()

    # ------------------------------------------------------------------ IK
    def _checker(self, q):
        key = round(float(q), 4)
        if key not in self._checkers:
            while len(self._checkers) >= self.cfg["checkers_kept"]:
                self._checkers.pop(next(iter(self._checkers)))
            self._checkers[key] = ArmCollisionChecker(self.model, SIDE, TASK_CFG["home_q_right"], finger_open=STAGING_CFG["finger_open"], pedestal_q=float(q))
        else:
            self._checkers[key] = self._checkers.pop(key)
        return self._checkers[key]

    def to_torso(self, stance, P):
        x, y, th, q = stance
        c, s = math.cos(th), math.sin(th)
        dx, dy = P[:, 0] - x, P[:, 1] - y
        tz = self.rg["base_z"] + self.rg["torso_z0"] + self.rg["lift_factor"] * q
        return np.stack([c * dx + s * dy, -s * dx + c * dy, P[:, 2] - tz], axis=-1)

    def _bin_order(self, point, t, approach_bin):
        """The approach directions to try for a point, in order. A required direction (the point's own or `approach_bin`) is the only one; otherwise the reach maps' reachable directions first (by the angle to the shoulder-to-target direction), then the others."""
        req = point.get("bin") if point.get("bin") is not None else approach_bin
        if req is not None:
            return [int(req)]
        az = math.atan2(t[1] - self.shoulder[1], t[0] - self.shoulder[0])
        ang = np.abs((az - self.centres + math.pi) % (2 * math.pi) - math.pi)
        ordered = [int(k) for k in np.argsort(ang)]
        reach = []
        for k in ordered:
            rm = self.maps.get((SIDE, k))
            if rm is None:
                continue
            r = t - self.shoulder
            ix, iy, iz = (int(math.floor((r[j] - rm.origin[j]) / rm.cube)) for j in range(3))
            if 0 <= ix < rm.cubes.shape[0] and 0 <= iy < rm.cubes.shape[1] and 0 <= iz < rm.cubes.shape[2] and rm.cubes[ix, iy, iz]:
                reach.append(k)
        return reach + [k for k in ordered if k not in reach]

    def _admissible(self, stance, Q, prev, flip_ok_prev):
        """Which candidate joint vectors (c, 7) are usable: no collision of the arm with the robot, clear of the furniture and the objects, no elbow flip against `prev` (the previous point of the same path)."""
        cfg = self.cfg
        n = len(Q)
        ok = np.ones(n, bool)
        ok &= ~self._checker(stance[3]).check(Q)
        if flip_ok_prev and prev is not None:
            ok &= np.max(np.abs(Q - prev), axis=1) <= cfg["ik_flip_rad"]
        idx = np.nonzero(ok)[0]
        if len(idx):
            hm, am, _, _ = self.clear.arm_distances(stance, Q[idx])
            good = (hm >= cfg["hand_clearance"]) & (am > cfg["arm_clearance"])
            ok[idx[~good]] = False
        return ok

    def _pose_target(self, stance, pt, t, theta):
        """The exact target of a skill point in the torso frame: (pad centre (3,), tool frame rotation (3, 3)). A "skill" point keeps the skill's level, straight-forward hand; a "place" point has the hand
        turned by `theta` (radians, counter-clockwise seen from above) about the vertical axis through the beaker's centre (pt["pivot"], world xy), the pad centre turning with it."""
        R = self.R_skill
        if pt["pose"] == "place" and theta:
            c = self.to_torso(stance, np.array([[pt["pivot"][0], pt["pivot"][1], 0.0]]))[0]
            co, si = math.cos(theta), math.sin(theta)
            d = t[:2] - c[:2]
            t = np.array([c[0] + co * d[0] - si * d[1], c[1] + si * d[0] + co * d[1], t[2]])
            R = np.array([[co, -si, 0.0], [si, co, 0.0], [0.0, 0.0, 1.0]]) @ R
        return t, R

    def _log_stop(self, stance, pt, theta, starts, labels, ok, source, phase_ok, rescue, rescuable):
        """One entry of `start_log` per stop solved (the checker-start measurement, M187): the stance, the stop (path, pose kind, point), the start labels tried first, whether the stop passed and from which start
        ("random" = the random phase), `rescue` (today's mode: the starts tried first all failed and a random start passed it) and `forced_random` (no start was available: random was the only way),
        `rescuable` (the neighbourhood mode: the stop FAILED from its starts, but a random start could have reached it; logged only)."""
        self.start_log.append({"stance": [round(float(v), 4) for v in stance], "theta_deg": None if pt.get("pose") != "place" else round(math.degrees(theta)), "path": pt.get("path"), "pose": pt.get("pose"),
                               "p": [round(float(v), 4) for v in pt["p"]], "tried_first": list(labels), "ok": bool(ok), "source": source, "rescue": bool(rescue), "forced_random": bool(ok and source == "random" and not starts),
                               "rescuable": rescuable})

    def _log_ik(self, pt, phase, iters, accepted):
        """One batch of the exact-pose IK of a skill stop, for the pose_ik_iterations report: the iterations each start used (`iters`; the limit means it did not converge) and those of the accepted
        start (None: no start of the batch was accepted)."""
        self.pose_ik_log.append({"path": pt.get("path"), "phase": phase, "starts": int(len(iters)), "batch_max": int(np.max(iters)), "batch_at_limit": int(np.sum(iters >= self.cfg["pose_ik_iterations"])), "accepted": accepted})

    def _solve_pose_point(self, stance, pt, t, theta, prev, warm):
        """The IK of one skill point at the skill's own pose (no turn or tilt allowance): reached within the episode's waypoint tolerance (PICK_PLACE_CFG tol_m, tol_rad) and admissible (no collision,
        clear of the furniture and the objects, no elbow flip against `prev`). Returns (joint vector, None, source) or None."""
        C, cfg = self.C, self.cfg
        tp, R = self._pose_target(stance, pt, t, theta)
        mode = cfg.get("start_mode", "today")
        starts, labels = [], []
        if mode == "neighbourhood":                        # as the robot: the first stop from the zombie pose, later ones from the previous stop's answer; no random rescue decides
            starts, labels = ([prev], ["previous point"]) if prev is not None else ([self.zombie_q], ["zombie pose"])
        else:
            if warm is not None and not np.isnan(warm).any():
                starts.append(warm); labels.append("nominal")
            if prev is not None:
                starts.append(prev); labels.append("previous point")
        tol_m, tol_rad = PICK_PLACE_CFG["tol_m"], PICK_PLACE_CFG["tol_rad"]
        for phase in ("warm", "random"):
            if phase == "warm":
                if not starts:
                    continue
                Q0 = np.array(starts)
            else:
                Q0 = self.rng.uniform(self.lo, self.hi, (cfg["ik_seeds"], 7))
            t0 = time.perf_counter()
            Q, _, iters = solve_ik(self.chain, Q0, self.lo, self.hi, make_pose_constraint(np.repeat(tp[None, :], len(Q0), axis=0), R), self.pad, cfg["pose_ik_iterations"], C["ik_damping"], C["ik_max_step"])
            p, Rf = batch_fk(self.chain, Q, self.pad)
            err = np.linalg.norm(p - tp, axis=1)
            ang = np.linalg.norm(Rotation.from_matrix(R[None] @ Rf.transpose(0, 2, 1)).as_rotvec(), axis=1)
            good = (err <= tol_m) & (ang <= tol_rad)
            self.stats["ik_batches"] = self.stats.get("ik_batches", 0) + 1
            self.stats["ik_starts"] = self.stats.get("ik_starts", 0) + len(Q0)
            self.stats["ik_iterations"] = self.stats.get("ik_iterations", 0) + int(np.sum(iters))
            self.seconds["ik_solve"] = self.seconds.get("ik_solve", 0.0) + time.perf_counter() - t0
            cand = np.nonzero(good)[0]
            if not len(cand):
                self._log_ik(pt, phase, iters, None)
                continue
            t0 = time.perf_counter()
            adm = self._admissible(stance, Q[cand], prev, True)
            self.seconds["ik_admissible"] = self.seconds.get("ik_admissible", 0.0) + time.perf_counter() - t0
            if adm.any():
                j = cand[int(np.argmax(adm))]
                self._log_ik(pt, phase, iters, int(iters[j]))
                src = labels[j] if phase == "warm" and j < len(labels) else "random"
                if mode == "neighbourhood" and phase == "random":      # diagnostic only: another arm shape could reach it, but the robot would not get there from here
                    self._log_stop(stance, pt, theta, starts, labels, False, None, False, False, True)
                    return None
                self._log_stop(stance, pt, theta, starts, labels, True, src, True, phase == "random" and bool(starts), None)
                return Q[j], None, src
        self._log_stop(stance, pt, theta, starts, labels, False, None, False, False, False if mode == "neighbourhood" else None)
        return None

    def _solve_stance(self, stance, points, approach_bin, warm=None, theta=0.0):
        """The IK path check at one stance: for every point in order a joint solution (first success), or the first point that fails. Returns a dict.

        A point with "pose" "skill" or "place" is solved at the skill's own pose (`_solve_pose_point`; a "place" point with the hand turned by `theta` radians); any other point as a grasp in any bin."""
        C, cfg = self.C, self.cfg
        P = np.array([pt["p"] for pt in points], float)
        T = self.to_torso(stance, P)
        sol = np.full((len(points), 7), np.nan)
        info = {"ok": True, "failed_point": None, "bins": [], "sources": [], "tried_bins": 0}
        for i, pt in enumerate(points):
            prev = sol[i - 1] if i > 0 and points[i - 1].get("path") == pt.get("path") and not np.isnan(sol[i - 1]).any() else None
            found = None
            if pt.get("pose") in ("skill", "place"):
                found = self._solve_pose_point(stance, pt, T[i], theta, prev, None if warm is None else warm[i])
                if found is None:
                    info.update(ok=False, failed_point=i, failed_path=pt.get("path"))
                    break
                sol[i] = found[0]
                info["bins"].append(None); info["sources"].append(found[2])
                continue
            for k in self._bin_order(pt, T[i], approach_bin):
                info["tried_bins"] += 1
                starts, labels = [], []
                if warm is not None and not np.isnan(warm[i]).any():
                    starts.append(warm[i]); labels.append("nominal")
                if prev is not None:
                    starts.append(prev); labels.append("previous point")
                for phase in ("warm", "random"):
                    if phase == "warm":
                        if not starts:
                            continue
                        Q0 = np.array(starts)
                    else:
                        Q0 = self.rng.uniform(self.lo, self.hi, (cfg["ik_seeds"], 7))
                    t0 = time.perf_counter()
                    Q, good, iters = solve_ik(self.chain, Q0, self.lo, self.hi, make_constraint(np.repeat(T[i][None, :], len(Q0), axis=0), k, C), self.pad,
                                              C["ik_max_iter"], C["ik_damping"], C["ik_max_step"])
                    self.stats["ik_batches"] = self.stats.get("ik_batches", 0) + 1
                    self.stats["ik_starts"] = self.stats.get("ik_starts", 0) + len(Q0)
                    self.stats["ik_iterations"] = self.stats.get("ik_iterations", 0) + int(np.sum(iters))
                    self.seconds["ik_solve"] = self.seconds.get("ik_solve", 0.0) + time.perf_counter() - t0
                    cand = np.nonzero(good)[0]
                    if not len(cand):
                        continue
                    t0 = time.perf_counter()
                    adm = self._admissible(stance, Q[cand], prev, True)
                    self.seconds["ik_admissible"] = self.seconds.get("ik_admissible", 0.0) + time.perf_counter() - t0
                    if adm.any():
                        j = cand[int(np.argmax(adm))]
                        found = (Q[j], k, labels[j] if phase == "warm" and j < len(labels) else "random")
                        break
                if found:
                    break
            if found is None:
                info.update(ok=False, failed_point=i, failed_path=pt.get("path"))
                break
            sol[i] = found[0]
            info["bins"].append(found[1]); info["sources"].append(found[2])
        info["solution"] = sol
        return info

    def _error_stances(self, stance):
        e, (x, y, th, q) = self.cfg["error_budget"], stance
        dh = math.radians(e["heading_deg"])
        out = [("nominal", (x, y, th, q))]
        out += [(f"x{sg:+d}", (x + sg * e["x"], y, th, q)) for sg in (1, -1)]
        out += [(f"y{sg:+d}", (x, y + sg * e["y"], th, q)) for sg in (1, -1)]
        out += [(f"heading{sg:+d}", (x, y, th + sg * dh, q)) for sg in (1, -1)]
        out += [(f"pedestal{sg:+d}", (x, y, th, float(np.clip(q + sg * e["pedestal"], 0.0, robot_specs.PEDESTAL_SPECS["range"][1])))) for sg in (1, -1)]
        return out

    def _place_window(self, stances, place_pts):
        """The hand turns at which the whole place works (Part 5, M183): for each turn theta of `place_turn_step_deg` steps all the way round (0 to 355 degrees, counter-clockwise seen from above), every place
        stop (the carry stop over the destination, the lowering stops, the back-off) is reached within the episode's own waypoint tolerance and admissible (the collision tests) at the nominal stance and at
        each error stance. The working window is a run of consecutive working turns (around the circle); the widest is chosen and the middle turn of it.

        Args:
            stances (list of tuple): [(name, (x, y, th, q))]: the nominal stance first, then each error stance (`_error_stances`).
            place_pts (list of dict): The "place" points in the skill's order.

        Returns:
            dict: "theta_deg" (the chosen turn or None), "window_deg" ([first, last] of the chosen window), "width_deg", "passing_deg" (every working turn), "windows" (every run [first, last]),
            "failed_stop" (per failing turn at the nominal stance: the path name of the first stop that failed, or the error stance that failed), "reason" (when no window is wide enough).
        """
        cfg = self.cfg
        step, need = cfg["place_turn_step_deg"], cfg["place_turn_min_window_deg"]
        passing, failed_at, warm = [], {}, None
        for deg in range(0, 360, step):
            th = math.radians(deg)
            ok, nominal_sol = True, None
            for name, s in stances:
                info = self._solve_stance(s, place_pts, None, warm if name == "nominal" else nominal_sol, theta=th)
                if not info["ok"]:
                    failed_at[deg] = (name, info.get("failed_path"))
                    ok = False
                    break
                if name == "nominal":
                    nominal_sol = info["solution"]
            if ok:
                passing.append(deg)
                warm = nominal_sol
        out = choose_place_window(passing, step, need)
        out["failed_stop"] = {_wrap_deg(d): v for d, v in failed_at.items()}
        if not out["windows"]:
            counts = {}
            for _, (nm, pth) in failed_at.items():
                counts[(nm, pth)] = counts.get((nm, pth), 0) + 1
            top = sorted(counts.items(), key=lambda kv: -kv[1])[:2]
            out["reason"] = "no place angle window: no hand turn reaches every place stop within the tolerance and passes the collision tests (most common failure: " + "; ".join(f"stance '{k[0]}' stop '{k[1]}' at {v} turns" for k, v in top) + ")"
        return out

    def place_theta_at(self, stance, place_pts):
        """The place angle search at one stance (what the robot does when no stance selection chose an angle: navigation off, the reference stance): the same `_place_window` over the nominal stance and
        the error stances, on the "place" points only. Returns the `_place_window` dict ("theta_deg" None and "reason" when there is no window)."""
        return self._place_window(self._error_stances(tuple(stance)), place_pts)

    # ------------------------------------------------------------------ the check
    def check(self, stance, points, objects=(), source_data=None, approach_bin=None, use_cache=True):
        """The full check of a stance candidate.

        Args:
            stance (tuple): (x, y, heading, pedestal command): the middle pedestal height of the candidate.
            points (list of dict): The task points (task_points()).
            objects (list of dict): The unknown objects on the table (see the module docstring). Defaults to none.
            source_data (mujoco.MjData or None): A running simulation's data, read for the object poses (never changed). Defaults to None: the check's own scene.
            approach_bin (int or None): A required approach direction for every point that has none of its own. Defaults to None.
            use_cache (bool): Reuse the answer if nothing it depends on has changed. Defaults to True.

        Returns:
            dict: "ok", "failed" (names), "reason", "heights" (per height: the clearances, the view margin and the occlusion numbers), "ik" (per error stance: ok, the failed point, sources), "seconds"
            (per part), "stats" (IK counters), "cached" (bool), "key" (the first 12 hex digits).
        """
        t_all = time.perf_counter()
        if source_data is not None:
            self.sync(source_data)
        self.set_objects(list(objects))
        key = self._key(stance, points, objects, approach_bin)
        if use_cache and key in self.cache:
            r = dict(self.cache[key])
            r.update(cached=True, seconds={"total": round(time.perf_counter() - t_all, 4)})
            return r
        cfg, chk = self.cfg, self.chk
        self.stats, self.seconds = {}, {}
        x, y, th, q0 = stance
        heights = [float(np.clip(q0 + off, 0.0, robot_specs.PEDESTAL_SPECS["range"][1])) for off in cfg["height_offsets"]]
        res = {"ok": False, "failed": [], "reason": "", "heights": [], "ik": [], "cached": False, "key": key[:12], "stance": [float(v) for v in stance]}

        def finish(failed, reason):
            res.update(ok=not failed, failed=failed, reason=reason, stats=dict(self.stats))
            self.seconds["total"] = time.perf_counter() - t_all
            res["seconds"] = {k: round(v, 3) for k, v in self.seconds.items()}
            self.cache[key] = res
            return res

        def timed(name, fn, *a, **k):
            t0 = time.perf_counter()
            out = fn(*a, **k)
            self.seconds[name] = self.seconds.get(name, 0.0) + time.perf_counter() - t0
            return out
        # 1. clearances at the heights
        for h in heights:
            st = (x, y, th, h)
            hc = timed("clearance", chk.home_clearance, st)
            pb = timed("clearance", chk.beaker_on_hotplate_clearance, st)
            row = {"q": h, "home_clearance_mm": 1000 * hc["arms"], "home_pair": hc["arms_pair"], "placed_beaker_mm": None if pb is None else 1000 * pb}
            res["heights"].append(row)
            if hc["arms"] < STANCE_REQUIREMENTS["home_min_clearance"]:
                return finish(["home_clearance"], f"at pedestal {h:.3f} the arms at home are {1000 * hc['arms']:.0f} mm from {hc['arms_pair']} (the limit is {1000 * STANCE_REQUIREMENTS['home_min_clearance']:.0f} mm)")
            if pb is not None and pb < STANCE_REQUIREMENTS["placed_beaker_min_clearance"]:
                return finish(["placed_beaker"], f"at pedestal {h:.3f} the arms at home are {1000 * pb:.0f} mm from a beaker placed on the hotplate")
        # 2. the IK path check: the nominal stance and each error on its own
        nominal = None
        stances = self._error_stances((x, y, th, q0))
        place_pts = [pt for pt in points if pt.get("pose") == "place"]
        points = [pt for pt in points if pt.get("pose") != "place"]      # the place points are tested over the hand turns below (P3 part 5, M183)
        for name, s in stances:
            bd, pair = timed("body", self.clear.body_distance, s)
            if bd <= cfg["body_clearance"]:
                res["ik"].append({"stance": name, "ok": False, "failed_point": None})
                return finish(["body"], f"at the stance '{name}' the robot touches {pair}")
            info = timed("ik", self._solve_stance, s, points, approach_bin, None if nominal is None else nominal["solution"])
            res["ik"].append({"stance": name, "ok": info["ok"], "failed_point": info["failed_point"], "tried_bins": info["tried_bins"],
                              "sources": {k: info["sources"].count(k) for k in set(info["sources"])}})
            if not info["ok"]:
                pt = points[info["failed_point"]]
                return finish(["ik"], f"at the stance '{name}' point {info['failed_point']} ({pt.get('path')}, {np.round(pt['p'], 3).tolist()}) has no collision-free solution")
            if nominal is None:
                nominal = info
        if place_pts:
            win = timed("place_window", self._place_window, stances, place_pts)
            res["place"] = win
            if win["theta_deg"] is None:
                return finish(["place_angle_window"], win["reason"])
        # 3. the fixed view and the occlusion at the heights
        for h, row in zip(heights, res["heights"]):
            st = (x, y, th, h)
            vm = timed("view", chk.view_margin, st)
            row["view_margin"] = vm["margin"]
            if vm["margin"] < STANCE_REQUIREMENTS["view_min_margin"]:
                return finish(["view"], f"at pedestal {h:.3f} {vm['limit']} is {100 * vm['margin']:.1f} % from the nearest edge of the eagle image (limit {100 * STANCE_REQUIREMENTS['view_min_margin']:.0f} %)")
            oc = timed("occlusion", chk.occlusion, st)
            row.update(beaker_hidden=oc["beaker_hidden_frac"], hotplate_hidden=oc["hotplate_hidden_frac"], arm_frac=oc["arm_frac"])
            lim = STANCE_REQUIREMENTS["occlusion_max_hidden"]
            if oc["beaker_hidden_frac"] > lim["beaker"] or oc["hotplate_hidden_frac"] > lim["hotplate"]:
                return finish(["occlusion"], f"at pedestal {h:.3f} something hides {100 * oc['beaker_hidden_frac']:.1f} % of the beaker and {100 * oc['hotplate_hidden_frac']:.1f} % of the hotplate in the eagle image")
        return finish([], "")
